    },
    {
      "i": 7,
      "speaker": "bot",
      "text": "आपको internal storage 32 GB चाहिए ना?"
    },
    {
      "i": 8,
      "speaker": "caller",
      "text": "जी वैसे second hand phone ढूंढ रहा था वही देख रहा था।"
    },
    {
      "i": 9,
      "speaker": "bot",
      "text": "समझ गई।"
    },
    {
      "i": 10,
      "speaker": "bot",
      "text": "अब brand के बारे में बात कर लेते हैं।"
    },
    {
      "i": 11,
      "speaker": "caller",
      "text": "brand के बारे में।"
    },
    {
      "i": 12,
      "speaker": "bot",
      "text": "जी तो आप brand में क्या prefer करेंगे Samsung, Apple या कोई और?"
    },
    {
      "i": 13,
      "speaker": "caller",
      "text": "prefer करेंगे?"
    },
    {
      "i": 14,
      "speaker": "caller",
      "text": "वो।"
    },
    {
      "i": 15,
      "speaker": "bot",
      "text": "ठीक है मैं देख सकती हूं कि आपने RAM में 3 GB चुना है right?"
    },
    {
      "i": 16,
      "speaker": "caller",
      "text": "हाँ RAM RAM का तो मैं ये 6 GB वाला सुना था।"
    },
    {
      "i": 17,
      "speaker": "bot",
      "text": "ठीक है समझ गई।"
    },
    {
      "i": 18,
      "speaker": "bot",
      "text": "आपको मैं seller details WhatsApp पे भेज दूंगी जिनसे आप details और price discuss कर सकते हैं।"
    },
    {
      "i": 19,
      "speaker": "caller",
      "text": "ठीक है तो दीजिए।"
    },
    {
      "i": 20,
      "speaker": "bot",
      "text": "IndiaMART चुनने के लिए धन्यवाद।"
    },
    {
      "i": 21,
      "speaker": "bot",
      "text": "आपका दिन शुभ हो।"
    },
    {
      "i": 22,
      "speaker": "caller",
      "text": "Thank you."
    },
    {
      "i": 23,
